<style>body{margin:0;font-family:Arial;background:#f4f7fb;color:#111827}.layout{display:grid;grid-template-columns:280px 1fr;min-height:100vh}.sidebar{background:#111827;color:white;padding:30px}.logo{font-size:26px;font-weight:900;margin-bottom:30px}.menu a,.logout-btn{display:block;color:white;text-decoration:none;font-weight:800;margin:14px 0;background:#ffffff1a;padding:13px;border-radius:12px}.menu a.active{background:#4361ee}.logout-btn{width:100%;border:0;text-align:left}.content{padding:36px;min-width:0}.panel{background:white;border-radius:18px;padding:22px;box-shadow:0 10px 24px #0001;margin:22px 0}.tabs{display:flex;gap:8px}.tab,.btn{padding:11px 15px;border:0;border-radius:9px;font-weight:900;cursor:pointer}.tab.active,.btn{background:#4361ee;color:white}.pane{display:none}.pane.active{display:block}.filters{display:grid;grid-template-columns:repeat(4,minmax(140px,1fr));gap:12px;margin-bottom:20px}.filters label{display:block;font-weight:800;font-size:13px}.filters input,.filters select{width:100%;box-sizing:border-box;padding:9px;border:1px solid #cbd5e1;border-radius:8px}.btn{text-decoration:none;display:inline-block}table{width:100%;border-collapse:collapse}th,td{padding:10px;border-bottom:1px solid #e5e7eb;text-align:left;vertical-align:top;font-size:13px}th{background:#f8fafc}.scroll{overflow:auto}.muted{color:#64748b}.badge{display:inline-block;padding:5px 9px;border-radius:999px;background:#e2e8f0;font-weight:900}.green{background:#dcfce7;color:#166534}.yellow{background:#fef3c7;color:#92400e}.red{background:#fee2e2;color:#991b1b}.attention{background:#7f1d1d;color:white;border:2px solid #ef4444}</style></head><body><div class="layout">@include('crm.partials.sidebar')<main class="content">
<h1>Pagos B2C</h1><p class="muted">Pagos de envíos, recargas y movimientos de saldo. Módulo de sólo lectura.</p><section class="panel tabs"><button class="tab active" data-tab="shipments">Pagos de envíos</button><button class="tab" data-tab="recharges">Recargas prepago</button></section>
