$dash=fn($v)=>filled($v)?$v:'—';
$payLabel=fn($v)=>match(strtolower(trim((string)$v))){'approved'=>'Aprobado','pending','in_process'=>'Pendiente','rejected','cancelled','cancelled_by_user'=>'Rechazado','saldo_prepago'=>'Pagado con saldo','saldo_revertido','refunded','charged_back'=>'Reembolsado',default=>'Sin información'};
$recLabel=function($r){$ok=$r->movimiento&&$r->movimiento->estatus==='APLICADO'&&(float)$r->movimiento->saldo_nuevo>(float)$r->movimiento->saldo_anterior;if($ok)return 'Acreditada';if(strtolower((string)$r->mp_status)==='approved'||strtoupper((string)$r->estatus)==='APROBADA')return 'Aprobada no acreditada';return match(strtoupper((string)$r->estatus)){'PENDIENTE'=>'Pendiente','RECHAZADA'=>'Rechazada','ERROR'=>'Error',default=>'Creada'};};
