<div class="scroll"><table><thead><tr><th>Cotización</th><th>Cliente / email</th><th>Mensajería / servicio</th><th>Monto / moneda</th><th>Método</th><th>payment_id</th><th>payment_status</th><th>Estatus envío</th><th>Fecha de pago</th><th></th></tr></thead><tbody>@forelse($shipments as $s)<tr><td>#{{$s->id}}</td><td><strong>{{$dash($s->user?->name)}}</strong><br><span class="muted">{{$dash($s->user?->email)}}</span></td><td>{{$dash($s->logistico)}} / {{$dash($s->servicio)}}</td><td>${{number_format((float)($s->payment_verified_amount?:$s->precio),2)}} {{$dash($s->payment_verified_currency?:'MXN')}}</td><td>{{strtolower((string)$s->payment_status)==='saldo_prepago'?'Saldo prepago':'Mercado Pago'}}</td><td>{{$dash($s->payment_id)}}</td><td><span class="badge">{{$payLabel($s->payment_status)}}</span></td><td>{{$dash($s->estatus_label)}}</td><td>{{$s->payment_verified_at?->format('d/m/Y H:i')??$s->updated_at?->format('d/m/Y H:i')??'—'}}</td><td><a class="btn" href="{{route('crm.pagos.envios.show',$s)}}">Ver detalle</a></td></tr>@empty<tr><td colspan="10">No se encontraron pagos.</td></tr>@endforelse</tbody></table></div><div style="margin-top:18px">{{$shipments->links()}}</div></section>
